// ─── File: CsrfDefenseDemo.java ───
package com.bank.csrf;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CsrfDefenseDemo {
    private static final Logger log = Logger.getLogger(CsrfDefenseDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CsrfProtectedTransferService service = new CsrfProtectedTransferService();
        String sessionId = "sess-rajesh";

        // The bank's own page receives a CSRF token bound to the session.
        String realToken = service.issueCsrfToken(sessionId);
        log.info(() -> "Bank page holds CSRF token for the session");

        // Legitimate transfer: request carries the correct token.
        service.transfer(sessionId, realToken, "SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info("Legitimate transfer accepted (valid CSRF token)");

        // Forged transfer from a malicious site: cookie auto-sent, but NO valid token.
        try {
            service.transfer(sessionId, "guessed-or-missing", "SAV2001", "ATTACKER99", new BigDecimal("50000"));
        } catch (CsrfValidationException e) {
            log.severe("Forged (CSRF) transfer rejected: " + e.getMessage());
        }

        // SameSite=Strict: browser would not even send the cookie cross-site.
        boolean sent = SameSiteCookie.wouldSendCrossSite("Strict");
        log.info(() -> "Cookie sent on cross-site request (SameSite=Strict)? " + sent);
    }
}

