class CsrfValidationException extends RuntimeException {
    CsrfValidationException(String m) { super(m); }
}

// ─── Would be in CsrfProtectedTransferService.java ───
class CsrfProtectedTransferService {
    private final Map<String, String> sessionToToken = new HashMap<>();

    String issueCsrfToken(String sessionId) {
        String token = UUID.randomUUID().toString(); // unguessable, per session
        sessionToToken.put(sessionId, token);
        return token;
    }

    void transfer(String sessionId, String presentedToken, String from, String to, BigDecimal amount) {
        String expected = sessionToToken.get(sessionId);
        if (expected == null || !expected.equals(presentedToken))
            throw new CsrfValidationException("missing or invalid CSRF token");
        // ... proceed with the real debit/credit (omitted) ...
    }
}

// ─── Would be in SameSiteCookie.java ───
class SameSiteCookie {
    // Models browser behavior: Strict/Lax do NOT attach the cookie cross-site.
    static boolean wouldSendCrossSite(String sameSite) {
        return !("Strict".equalsIgnoreCase(sameSite) || "Lax".equalsIgnoreCase(sameSite));
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
